def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    my_d = sum(1 for a in my if a == 'D')

    # Early game: be forgiving. Only defect if opponent defected twice in a row.
    if n < 5:
        if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
            return 'D'
        return 'C'

    # If opponent has been defecting a lot overall, defect.
    if opp_d > n * 0.6:
        return 'D'

    # If opponent defected in the last two rounds, defect.
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    # If opponent defected last round, decide whether to retaliate or forgive.
    if opp[-1] == 'D':
        # If overall defection rate is low, forgive to break cycles.
        if opp_d <= n * 0.2:
            return 'C'
        else:
            return 'D'

    # If we defected last round and opponent cooperated, apologize.
    if my[-1] == 'D':
        return 'C'

    # AllC detection: if opponent has never defected and we have never defected.
    if opp_d == 0 and my_d == 0 and n >= 50:
        return 'D'  # probe

    # If we have probed and opponent still has 0 defections, they are AllC. Exploit.
    if opp_d == 0 and my_d > 0:
        first_my_d = -1
        for i in range(n):
            if my[i] == 'D':
                first_my_d = i
                break
        if first_my_d != -1 and n - 1 - first_my_d >= 1:
            return 'D'  # exploit AllC
        else:
            return 'C'  # apologize for probe

    # Default: cooperate.
    return 'C'
